#version 300 es
precision mediump float;

in vec2 vUv;
out vec4 fragColor;

uniform sampler2D u_input_base;
uniform sampler2D u_stamp_tex;
uniform vec4 u_base_color;   // color
uniform float u_stamp_size;  // [0.1, 50, 1]

uniform float u_grid_scale_x; // [1, 100, 10]
uniform float u_grid_scale_y; // [1, 100, 10]
uniform float u_scan_radius;  // [1, 3, 1]
uniform float u_render_order; // [0, 1, 0]

uniform vec2 u_resolution; // resolution

vec4 over(vec4 dst, vec4 src) {
    float outA = src.a + dst.a * (1.0 - src.a);
    vec3 outRGB = dst.rgb * (1.0 - src.a) + src.rgb * src.a;
    return vec4(outRGB, outA);
}

float sampleStamp(vec2 p, vec2 corner) {
    float aspect = (u_resolution.x / u_grid_scale_x) / (u_resolution.y / u_grid_scale_y);

    vec2 uv = p - corner;
    uv.x *= aspect;

    vec2 local = uv / u_stamp_size + 0.5;

    if (any(lessThan(local, vec2(0.0))) || any(greaterThan(local, vec2(1.0)))) {
        return 0.0;
    }

    return texture(u_stamp_tex, local).a;
}

void main() {
    vec2 gridUv = vUv * vec2(u_grid_scale_x, u_grid_scale_y);

    vec2 cellId  = floor(gridUv);
    vec2 localUv = fract(gridUv);

    vec2 invGrid = vec2(1.0 / u_grid_scale_x, 1.0 / u_grid_scale_y);

    int r     = int(round(u_scan_radius));
    int start = 1 - r;
    int end   = 1 + r;

    bool backToFront = u_render_order > 0.5;
    vec4 col = u_base_color;

    for (int jj = start; jj < end; jj++) {
        for (int ii = start; ii < end; ii++) {
            int i = backToFront ? ii : (end - 1 + start - ii);
            int j = backToFront ? (end - 1 + start - jj) : jj;
            vec2 corner = vec2(float(i), float(j));
            vec2 global = (cellId + corner) * invGrid;
            vec3 color  = texture(u_input_base, global).rgb;
            float alpha = sampleStamp(localUv, corner);
            col = over(col, vec4(color, alpha));
        }
    }

    fragColor = col;
}

#version 300 es
precision mediump float;

uniform sampler2D u_texture; 
uniform sampler2D u_gradientTexture; // gradient
in vec2 vUv;
out vec4 fragColor;

void main() {
  vec4 color = texture(u_texture, vUv);

  float brightness = dot(color.rgb, vec3(0.299, 0.587, 0.114));

  vec4 gradientColor = texture(u_gradientTexture, vec2(brightness, 0.5));

  fragColor = vec4(gradientColor.rgb, 1.0);
}

#version 300 es
precision mediump float;

uniform sampler2D u_texture; // input
uniform vec3 u_sourceColor; // color
uniform vec4 u_targetColor; // color [0, 0, 0, 0]
uniform float u_threshold; // [0, 1, 0.1]

in vec2 vUv;
out vec4 fragColor;

void main() {
    vec4 texColor = texture(u_texture, vUv);

    float colorDiff = distance(texColor.rgb, u_sourceColor) / 2.0;

    if (colorDiff < u_threshold) {
        fragColor = u_targetColor;
    } else {
        fragColor = texColor;
    }
}

#version 300 es
precision mediump float;

in vec2 vUv;
out vec4 fragColor;

uniform sampler2D u_texture_1;
uniform sampler2D u_texture_2;

void main() {
    fragColor = clamp(
        texture(u_texture_1, vUv) * texture(u_texture_2, vUv),
        vec4(0.),
        vec4(1.)
    );

}

#version 300 es
precision mediump float;

uniform vec2 u_resolution;  // resolution
uniform vec2 u_center;      // [0.5, 0.5]
uniform float u_rx;         // [0, 1, 0.4]
uniform float u_ry;         // [0, 1, 0.25]
uniform float u_feather;    // [0, 0.1, 0.01]
uniform float u_invert;     // [0, 1, 0]

in vec2 vUv;
out vec4 fragColor;

void main() {
    float aspect = u_resolution.x / u_resolution.y;
    vec2 uv = vec2((vUv.x - u_center.x) * aspect, vUv.y - u_center.y);

    // SDF for ellipse
    float d = length(uv / vec2(u_rx * aspect, u_ry)) - 1.0;

    float v = 1.0 - smoothstep(-u_feather, u_feather, d);
    v = mix(v, 1.0 - v, step(0.5, u_invert));

    fragColor = vec4(vec3(v), 1.0);
}

