#version 300 es
precision mediump float;

in vec2 vUv;
out vec4 fragColor;

uniform sampler2D u_input_tex; 
uniform vec2 u_tile; // [2, 2]
uniform vec2 u_resolution; // resolution
uniform float u_tile_scale; // [0.01, 100, 2]

void main() {
    vec2 tile_uv = fract(vUv * vec2(u_tile.x, u_tile.y));
    vec2 tile_aspect = vec2(u_tile.x / u_tile.y, 1.0);

    vec2 centered = tile_uv - 0.5;
    centered /= u_tile_scale;
    vec2 texture_space = centered / tile_aspect + 0.5;

    if (
        any(lessThan(texture_space, vec2(0.0))) ||
        any(greaterThan(texture_space, vec2(1.0)))
    ) {
        fragColor = vec4(vec3(0.0), 1.0);
        return;
    }

    fragColor = texture(
        u_input_tex,
        texture_space
    );
}

#version 300 es
precision mediump float;

// Author @patriciogv - 2015
// http://patriciogonzalezvivo.com

uniform vec2 u_resolution; // resolution
uniform float u_time;      // time
uniform float u_scale;     // [1, 20, 3]
uniform float u_octaves;   // [1, 12, 6]
uniform float u_speed;     // [0, 2, 0.1]

in vec2 vUv;
out vec4 fragColor;

float random(vec2 st) {
    return fract(sin(dot(st, vec2(12.9898, 78.233))) * 43758.5453123);
}

// Based on Morgan McGuire @morgan3d
// https://www.shadertoy.com/view/4dS3Wd
float noise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));

    vec2 u = f * f * (3.0 - 2.0 * f);

    return mix(a, b, u.x) +
           (c - a) * u.y * (1.0 - u.x) +
           (d - b) * u.x * u.y;
}

float fbm(vec2 st) {
    float value = 0.0;
    float amplitude = 0.5;
    int octaves = int(u_octaves);
    for (int i = 0; i < 12; i++) {
        if (i >= octaves) break;
        value += amplitude * noise(st);
        st *= 2.0;
        amplitude *= 0.5;
    }
    return value;
}

void main() {
    vec2 st = vUv * u_scale;
    st.x *= u_resolution.x / u_resolution.y;

    // animate by scrolling noise space over time
    st += u_time * u_speed;

    fragColor = vec4(vec3(fbm(st)), 1.0);
}

#version 300 es
precision highp float;

uniform vec2 u_resolution;  // resolution
uniform float u_time;       // time
uniform float u_roundness;    // [0, 0.5, 0.05]
uniform vec3 u_light_dir; // [1,1,0]
uniform vec3 u_rotation_rate; // [1,1,0]
uniform float u_distance;     // [1, 10, 3]

in vec2 vUv;
out vec4 fragColor;

vec3 rotX(vec3 p, float a) {
    float c = cos(a), s = sin(a);
    return vec3(p.x, c * p.y - s * p.z, s * p.y + c * p.z);
}

vec3 rotY(vec3 p, float a) {
    float c = cos(a), s = sin(a);
    return vec3(c * p.x + s * p.z, p.y, -s * p.x + c * p.z);
}

vec3 rotZ(vec3 p, float a) {
    float c = cos(a), s = sin(a);
    return vec3(c * p.x - s * p.y, s * p.x + c * p.y, p.z);
}

float sdRoundBox(vec3 p, vec3 b, float r) {
    vec3 q = abs(p) - b;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0) - r;
}

float scene(vec3 p) {
    vec3 q = rotX(p, u_time * u_rotation_rate.x);
    q = rotY(q, u_time * u_rotation_rate.y);
    q = rotZ(q, u_time * u_rotation_rate.z);
    return sdRoundBox(q, vec3(0.5 - u_roundness), u_roundness);
}

vec3 calcNormal(vec3 p) {
    vec2 e = vec2(0.001, 0.0);
    return normalize(vec3(
        scene(p + e.xyy) - scene(p - e.xyy),
        scene(p + e.yxy) - scene(p - e.yxy),
        scene(p + e.yyx) - scene(p - e.yyx)
    ));
}

void main() {
    vec2 uv = vUv * 2.0 - 1.0;
    uv.x *= u_resolution.x / u_resolution.y;

    vec3 ro = vec3(0.0, 0.0, u_distance);
    vec3 rd = normalize(vec3(uv, -1.5));

    float t = 0.0;
    bool hit = false;
    for (int i = 0; i < 80; i++) {
        float d = scene(ro + rd * t);
        if (d < 0.001) { hit = true; break; }
        if (t > 20.0) break;
        t += d;
    }

    float brightness = 0.0;
    if (hit) {
        vec3 p = ro + rd * t;
        vec3 n = calcNormal(p);
        vec3 l = normalize(u_light_dir);
        float diff = max(dot(n, l), 0.0);
        brightness = 0.12 + diff * 0.88;
    }

    fragColor = vec4(vec3(brightness), 1.0);
}
